//! Checks every sample file against fingerprints in tests/expected.json.
//!
//! The fingerprints were generated by scripts/golden.py from output that
//! scripts/compare.py had verified, value by value, against pandas.read_sas.

use arrow_array::cast::AsArray;
use arrow_array::types::{Date32Type, Float64Type, TimestampMillisecondType};
use arrow_array::{Array, RecordBatch};
use arrow_schema::{DataType, TimeUnit};
use sas2parquet::{ReadOptions, SasReader};
use serde_json::Value;
use std::path::Path;

#[derive(Default)]
struct Fingerprint {
    nulls: usize,
    sum: f64,
    chars: usize,
    first: Option<String>,
    last: Option<String>,
}

fn fingerprint(batches: &[RecordBatch], column: usize) -> Fingerprint {
    let mut fp = Fingerprint::default();
    for batch in batches {
        let array = batch.column(column);
        fp.nulls += array.null_count();
        match array.data_type() {
            DataType::Utf8 => {
                for value in array.as_string::<i32>().iter().flatten() {
                    fp.chars += value.chars().count();
                    fp.first.get_or_insert_with(|| value.to_string());
                    fp.last = Some(value.to_string());
                }
            }
            DataType::Float64 => {
                fp.sum += array
                    .as_primitive::<Float64Type>()
                    .iter()
                    .flatten()
                    .sum::<f64>()
            }
            DataType::Date32 => {
                fp.sum += array
                    .as_primitive::<Date32Type>()
                    .iter()
                    .flatten()
                    .map(f64::from)
                    .sum::<f64>()
            }
            DataType::Timestamp(TimeUnit::Millisecond, None) => {
                fp.sum += array
                    .as_primitive::<TimestampMillisecondType>()
                    .iter()
                    .flatten()
                    .map(|v| v as f64)
                    .sum::<f64>()
            }
            other => panic!("unexpected column type {other}"),
        }
    }
    fp
}

fn close(a: f64, b: f64) -> bool {
    a == b || (a - b).abs() <= 1e-9 * a.abs().max(b.abs())
}

fn check(name: &str, expected: &Value, batch_rows: usize) {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/data")
        .join(format!("{name}.sas7bdat"));
    let bytes = std::fs::read(&path).unwrap();
    let options = ReadOptions {
        batch_rows,
        ..ReadOptions::default()
    };
    let reader = SasReader::new(&bytes, &options).unwrap_or_else(|e| panic!("{name}: {e}"));
    let batches: Vec<RecordBatch> = (0..reader.num_batches())
        .map(|i| {
            reader
                .read_batch(i)
                .unwrap_or_else(|e| panic!("{name}: {e}"))
        })
        .collect();

    let rows: usize = batches.iter().map(RecordBatch::num_rows).sum();
    assert_eq!(
        rows as u64,
        expected["rows"].as_u64().unwrap(),
        "{name}: row count"
    );

    let schema = reader.schema();
    let columns = expected["columns"].as_object().unwrap();
    let names: Vec<&str> = schema.fields().iter().map(|f| f.name().as_str()).collect();
    let expected_names: Vec<&str> = columns.keys().map(String::as_str).collect();
    let mut sorted = names.clone();
    sorted.sort_unstable();
    assert_eq!(sorted, expected_names, "{name}: column names");

    for (i, column) in names.iter().enumerate() {
        let want = &columns[*column];
        let got = fingerprint(&batches, i);
        let ctx = format!("{name}.{column}");
        assert_eq!(
            got.nulls as u64,
            want["nulls"].as_u64().unwrap(),
            "{ctx}: nulls"
        );
        if let Some(sum) = want.get("sum").and_then(Value::as_f64) {
            assert!(close(got.sum, sum), "{ctx}: sum {} != {sum}", got.sum);
        } else {
            assert_eq!(
                got.chars as u64,
                want["chars"].as_u64().unwrap(),
                "{ctx}: chars"
            );
            assert_eq!(got.first.as_deref(), want["first"].as_str(), "{ctx}: first");
            assert_eq!(got.last.as_deref(), want["last"].as_str(), "{ctx}: last");
        }
    }
}

fn expected() -> serde_json::Map<String, Value> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/expected.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

#[test]
fn every_sample_file_matches_expected_values() {
    for (name, want) in expected() {
        check(&name, &want, ReadOptions::default().batch_rows);
    }
}

/// Batches are cut at page boundaries; tiny batches exercise the plan-splitting logic
/// and must not change the result.
#[test]
fn results_do_not_depend_on_batch_size() {
    for (name, want) in expected() {
        check(&name, &want, 1);
    }
}

#[test]
fn rejects_files_that_are_not_sas7bdat() {
    let err = SasReader::new(b"definitely not a sas file", &ReadOptions::default())
        .err()
        .unwrap();
    assert!(matches!(err, sas2parquet::Error::BadMagic));
}

#[test]
fn truncated_files_are_errors_not_panics() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/airline.sas7bdat");
    let bytes = std::fs::read(path).unwrap();
    for len in [100, 1024, bytes.len() / 2, bytes.len() - 1] {
        assert!(SasReader::new(&bytes[..len], &ReadOptions::default()).is_err());
    }
}

/// Corrupts one byte at a time across uncompressed, RLE and RDC files. Every outcome is
/// acceptable except a panic: malformed input must surface as an `Err`.
#[test]
fn corrupted_bytes_never_panic() {
    for name in ["airline", "ietest2", "binary"] {
        let path = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/data")
            .join(format!("{name}.sas7bdat"));
        let original = std::fs::read(path).unwrap();
        for position in (0..original.len()).step_by(7) {
            for value in [0x00, 0xFF, original[position] ^ 0x5A] {
                let mut bytes = original.clone();
                bytes[position] = value;
                if let Ok(reader) = SasReader::new(&bytes, &ReadOptions::default()) {
                    for i in 0..reader.num_batches() {
                        let _ = reader.read_batch(i);
                    }
                }
            }
        }
    }
}
